#!/usr/bin/env node
/* Open dataset generation (SEO L8a, approved 2026-11-14).
 *
 * Emits into dist/data/ on every build, straight from the same data
 * layer the pages render (src/data/site-data.json, regenerated by
 * build-data earlier in the chain) — never hand-assembled:
 *  - visa-requirements.csv           all pairs (39,402)
 *  - visa-requirements-verified.csv  only pairs verified against an
 *                                    official source, with the source
 *  - dataset.json                    manifest (counts, dates, licence)
 *
 * Licence: CC BY 4.0 — free to reuse with attribution. The live pages
 * are always the freshest version; the manifest says so and carries
 * the data's own latest verification date.
 */
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';

const sd = JSON.parse(readFileSync('src/data/site-data.json', 'utf8'));
const countries = sd.countries;
const byCode = Object.fromEntries(countries.map((c) => [c.code, c]));
const extras = sd.extras || {};
const STATUS_LABEL = {
  F: 'Visa free', A: 'Visa on arrival', E: 'e-Visa', T: 'Electronic travel authorisation',
  R: 'Visa required', N: 'No admission',
};

const q = (v) => {
  const s = v === null || v === undefined ? '' : String(v);
  return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
};
const HEADER = ['passport', 'passport_code', 'passport_slug', 'destination', 'destination_code',
  'destination_slug', 'status', 'status_label', 'max_stay_days', 'pair_url',
  'verified_against_official_source', 'verified_date', 'source_name', 'source_url'];

const rows = [];
let verifiedCount = 0;
let latestVerified = null;
for (const [pc, list] of Object.entries(sd.byPassport)) {
  const p = byCode[pc];
  for (const r of list) {
    const d = byCode[r.d];
    const ex = extras[`${pc}:${r.d}`] || {};
    const verified = ex.verified ? 'yes' : 'no';
    if (ex.verified) {
      verifiedCount += 1;
      if (!latestVerified || ex.verified > latestVerified) latestVerified = ex.verified;
    }
    rows.push([
      p.name, pc, p.slug, d.name, r.d, d.slug, r.s, STATUS_LABEL[r.s] || r.s,
      r.days === null || r.days === undefined ? '' : r.days,
      `https://visafreely.com/visa/${p.slug}/${d.slug}/`,
      verified, ex.verified || '', ex.source_name || '', ex.source || '',
    ]);
  }
}
rows.sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : a[3] < b[3] ? -1 : 1));

const toCsv = (rs) => [HEADER, ...rs].map((r) => r.map(q).join(',')).join('\n') + '\n';
mkdirSync('dist/data', { recursive: true });
const allCsv = toCsv(rows);
const verCsv = toCsv(rows.filter((r) => r[10] === 'yes'));
writeFileSync('dist/data/visa-requirements.csv', allCsv);
writeFileSync('dist/data/visa-requirements-verified.csv', verCsv);
const manifest = {
  name: 'visafreely visa requirements dataset',
  generated_at: new Date().toISOString(),
  data_vintage: sd.vintage,
  latest_verified_date: latestVerified,
  pairs_total: rows.length,
  pairs_verified: verifiedCount,
  licence: 'CC BY 4.0 — free to reuse with attribution to visafreely.com',
  licence_url: 'https://creativecommons.org/licenses/by/4.0/',
  note: 'Generated from the same data layer as visafreely.com on every deploy. The live pair pages are always the freshest version — cite the page, not just this file.',
  files: [
    { path: 'visa-requirements.csv', rows: rows.length, bytes: Buffer.byteLength(allCsv) },
    { path: 'visa-requirements-verified.csv', rows: verifiedCount, bytes: Buffer.byteLength(verCsv) },
  ],
};
writeFileSync('dist/data/dataset.json', JSON.stringify(manifest, null, 2) + '\n');
console.log(`dataset: pairs=${rows.length} verified=${verifiedCount} latest=${latestVerified}`);
